#!/usr/bin/env python3

import sys
import os

# Add the src directory to the path so we can import flask
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))

from flask import Blueprint

def test_whitespace_only_name():
    """Test that creating a Blueprint with whitespace-only name raises ValueError"""
    test_cases = [" ", "  ", "\t", "\n", " \t \n "]

    for name in test_cases:
        try:
            bp = Blueprint(name, __name__)
            print(f"ERROR: Blueprint with whitespace-only name '{repr(name)}' was created - this should not happen!")
            return False
        except ValueError as e:
            if "Blueprint name cannot be empty" in str(e):
                print(f"SUCCESS: Blueprint with whitespace-only name '{repr(name)}' correctly raised ValueError")
            else:
                print(f"ERROR: ValueError raised but with wrong message for '{repr(name)}':", str(e))
                return False
        except Exception as e:
            print(f"ERROR: Unexpected exception raised for '{repr(name)}':", type(e).__name__, str(e))
            return False

    return True

def test_none_name():
    """Test that creating a Blueprint with None name raises appropriate error"""
    try:
        bp = Blueprint(None, __name__)
        print("ERROR: Blueprint with None name was created - this should not happen!")
        return False
    except (ValueError, TypeError) as e:
        print("SUCCESS: Blueprint with None name correctly raised exception:", type(e).__name__, str(e))
        return True
    except Exception as e:
        print("ERROR: Unexpected exception raised:", type(e).__name__, str(e))
        return False

if __name__ == "__main__":
    print("Testing Blueprint edge cases...")

    tests = [
        test_whitespace_only_name,
        test_none_name
    ]

    results = []
    for test in tests:
        print(f"\nRunning {test.__name__}...")
        results.append(test())

    print(f"\nResults: {sum(results)}/{len(results)} tests passed")

    if all(results):
        print("All edge case tests passed!")
        sys.exit(0)
    else:
        print("Some edge case tests failed!")
        sys.exit(1)
